"""Generate a self-contained HTML dashboard snapshot."""
import html
from pathlib import Path
from .agent import LABELS
def build_dashboard(agent,output_path="dashboard.html"):
    s=agent.stats(); recent=agent.memory.recent(12)
    bars=''.join(f'<circle cx="555" cy="{85+i*30}" r="9" fill="#f3c969"/>' for i in range(3))
    rows=''.join(f"<tr><td>{r['id']}</td><td>{html.escape(r['label'])}</td><td>{html.escape(r['source'])}</td><td>{html.escape(r['text'])}</td></tr>" for r in recent) or '<tr><td colspan="4">No experiences yet</td></tr>'
    page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Neural Brains AI 2.0</title><style>*{{box-sizing:border-box}}body{{margin:0;background:#0b1020;color:#edf2ff;font:15px system-ui}}main{{max-width:1000px;margin:auto;padding:28px}}.muted{{color:#9eabc8}}.cards{{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px}}.card{{background:#151e34;border:1px solid #273653;border-radius:14px;padding:18px}}.big{{font-size:28px;font-weight:700}}svg{{width:100%;max-width:700px;background:#111a2d;border-radius:14px}}table{{width:100%;border-collapse:collapse;background:#151e34}}th,td{{padding:12px;text-align:left;border-bottom:1px solid #273653;overflow-wrap:anywhere}}</style></head><body><main><h1>Neural Brains AI <span class="muted">v2.0</span></h1><p class="muted">Local neural classifier, persistent model weights, and SQLite experience memory.</p><section class="cards"><div class="card">Stored experiences<div class="big">{s['experiences']}</div></div><div class="card">Training updates<div class="big">{s['training_updates']}</div></div><div class="card">Output classes<div class="big">{len(LABELS)}</div></div></section><h2>Network concept</h2><svg viewBox="0 0 660 210"><text x="25" y="30" fill="#b8c8e8">Input features</text><text x="280" y="30" fill="#b8c8e8">Hidden layer</text><text x="520" y="30" fill="#b8c8e8">Outputs</text>{''.join(f'<line x1="{90+i*8}" y1="{70+(i%6)*18}" x2="330" y2="{90+(i%5)*20}" stroke="#425779" opacity=".35"/>' for i in range(12))}{''.join(f'<circle cx="90" cy="{70+i*10}" r="4" fill="#8ab4ff"/>' for i in range(10))}{''.join(f'<circle cx="330" cy="{75+i*15}" r="7" fill="#79d6c2"/>' for i in range(8))}{bars}</svg><h2>Recent experiences</h2><table><thead><tr><th>ID</th><th>Label</th><th>Type</th><th>Text</th></tr></thead><tbody>{rows}</tbody></table><p class="muted">Static snapshot. Regenerate after new interactions to refresh it.</p></main></body></html>'''
    p=Path(output_path); p.parent.mkdir(parents=True,exist_ok=True); p.write_text(page,encoding="utf-8"); return p
